function def = f90_xauto04_definition
%F90_XAUTO04_DEFINITION Minimal direct-golden task definition.
root = localProjectRoot;
taskRoot = string(getenv("SIMUVERITY_TASK_ROOT"));
officialPath = simuverity_official_scenarios_path();
official = jsondecode(fileread(officialPath));
referenceFilePresence = lower(strtrim(string("present")));
assert(strlength(referenceFilePresence) > 0, ...
    "SimuVerity:Extractor:ReferenceIdentity", ...
    "Evaluator did not bind the expected reference file presence.");
def = struct( ...
    "id", "XAUTO04", ...
    "formal_id", "F90-XAUTO-04", ...
    "task_root", string(taskRoot), ...
    "reference_project_root", string(fullfile( ...
        taskRoot, "reference", "BrakingTest_R2025a")), ...
    "reference_model", string(fullfile( ...
        taskRoot, "reference", "BrakingTest_R2025a", ...
        "System", "BTReferenceApplication.slx")), ...
    "reference_file_presence", referenceFilePresence, ...
    "public_spec", string(fullfile(taskRoot, "public_spec.json")), ...
    "official_scenarios", string(officialPath), ...
    "scenarios", official.scenarios, ...
    "weights", official.weights, ...
    "required_outputs", [ ...
        "VehicleState", "WheelState", "BrakeState", "TireForceState"]);
end

function root = localProjectRoot
root = fileparts(mfilename("fullpath"));
for level = 1:4, root = fileparts(root); end
end
